import crypto from 'crypto';

function base64url(str) {
  return Buffer.from(str)
    .toString('base64')
    .replace(/=/g, '')
    .replace(/\+/g, '-')
    .replace(/\//g, '_');
}

function fromBase64url(str) {
  let s = str.replace(/-/g, '+').replace(/_/g, '/');
  while (s.length % 4) s += '=';
  return Buffer.from(s, 'base64').toString('utf8');
}

export function sign(payload, secret, options = {}) {
  const header = { alg: 'HS256', typ: 'JWT' };
  const now = Math.floor(Date.now() / 1000);
  
  let exp = now + 7 * 24 * 3600; // default 7 days
  if (options.expiresIn) {
    if (typeof options.expiresIn === 'number') {
      exp = now + options.expiresIn;
    } else if (typeof options.expiresIn === 'string') {
      const match = options.expiresIn.match(/^(\d+)([smhd])$/);
      if (match) {
        const val = parseInt(match[1]);
        const unit = match[2];
        const mult = unit === 's' ? 1 : unit === 'm' ? 60 : unit === 'h' ? 3600 : 86400;
        exp = now + val * mult;
      }
    }
  }

  const fullPayload = {
    ...payload,
    iat: now,
    exp
  };

  const headerB64 = base64url(JSON.stringify(header));
  const payloadB64 = base64url(JSON.stringify(fullPayload));
  const data = `${headerB64}.${payloadB64}`;

  const signature = crypto
    .createHmac('sha256', String(secret))
    .update(data)
    .digest('base64')
    .replace(/=/g, '')
    .replace(/\+/g, '-')
    .replace(/\//g, '_');

  return `${data}.${signature}`;
}

export function verify(token, secret, options = {}) {
  if (!token || typeof token !== 'string') {
    throw new Error('jwt must be provided');
  }

  const parts = token.split('.');
  if (parts.length !== 3) {
    throw new Error('jwt malformed');
  }

  const [headerB64, payloadB64, signatureB64] = parts;
  const data = `${headerB64}.${payloadB64}`;

  const expectedSig = crypto
    .createHmac('sha256', String(secret))
    .update(data)
    .digest('base64')
    .replace(/=/g, '')
    .replace(/\+/g, '-')
    .replace(/\//g, '_');

  if (signatureB64 !== expectedSig) {
    throw new Error('invalid signature');
  }

  const payload = JSON.parse(fromBase64url(payloadB64));
  const now = Math.floor(Date.now() / 1000);

  if (payload.exp && payload.exp < now) {
    throw new Error('jwt expired');
  }

  return payload;
}

export function decode(token) {
  if (!token) return null;
  const parts = token.split('.');
  if (parts.length < 2) return null;
  try {
    return JSON.parse(fromBase64url(parts[1]));
  } catch {
    return null;
  }
}

export default {
  sign,
  verify,
  decode
};
